  {"custom_id":"q1","params":{"model":"claude-haiku-5-5","max_tokens":256,
     "messages":[{"role":"user","content":"Summarize doc 1"}]}},
  {"custom_id":"q2","params":{"model":"claude-haiku-5-5","max_tokens":256,
     "messages":[{"role":"user","content":"Summarize doc 2"}]}},
])
while client.messages.batches.retrieve(batch.id).processing_status != "ended":
    time.sleep(60)
for r in client.messages.batches.results(batch.id):
    if r.result.type == "succeeded":
        print(r.custom_id, r.result.message.content[0].text)
